package com.gameaggregator.auditservice.application;import com.fasterxml.jackson.databind.ObjectMapper;import com.gameaggregator.auditservice.api.AuditDtos.Event;import com.gameaggregator.auditservice.domain.AuditLog;import com.gameaggregator.auditservice.infrastructure.AuditLogRepository;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;@Service public class AuditService{final AuditLogRepository repo;final ObjectMapper json;public AuditService(AuditLogRepository r,ObjectMapper j){repo=r;json=j;}@Transactional public AuditLog append(Event e){if(repo.existsByEventId(e.eventId()))return repo.findByEventId(e.eventId()).orElseThrow();return repo.save(new AuditLog(e.eventId(),e.tenantId(),e.actorId(),e.action(),e.resourceType(),e.resourceId(),e.requestId(),e.correlationId(),e.ipAddress(),e.beforeJson(),e.afterJson(),e.occurredAt()));}@KafkaListener(topics="audit-events",groupId="audit-service")public void consume(String payload){try{append(json.readValue(payload,Event.class));}catch(Exception e){throw new IllegalArgumentException("Invalid audit event",e);}}}